-- ============================================================
-- DB-20: test 侧 timestamptz 对齐 prod（169 列）
--
-- 范围：仅 topems_test（prod 机同实例），严禁在 topems_prod 执行。
-- 依据：prod 已为 timestamp with time zone、test 仍为 timestamp without time zone 的 169 列
--       （含 P5a 引入的 5 列：public.equipment 4 + iam.core_plugin_instances.last_heartbeat）。
-- 实测：169 列在 test 中全部为 NULL（非空行数 0），无 FK/视图/生成列依赖，无默认值。
-- 转换：USING col AT TIME ZONE 'UTC'（与 db04 / P5a 口径一致）。
-- 幂等：DO 块仅在当前类型为 timestamp without time zone 时执行。
-- ============================================================

SET lock_timeout = '5s';

DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='erp' AND t.relname='leave_requests' AND a.attname='deleted_at' AND NOT a.attisdropped AND a.atttypid='timestamp without time zone'::regtype) THEN ALTER TABLE erp.leave_requests ALTER COLUMN deleted_at TYPE timestamp with time zone USING deleted_at AT TIME ZONE 'UTC'; END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='iam' AND t.relname='core_plugin_instances' AND a.attname='last_heartbeat' AND NOT a.attisdropped AND a.atttypid='timestamp without time zone'::regtype) THEN ALTER TABLE iam.core_plugin_instances ALTER COLUMN last_heartbeat TYPE timestamp with time zone USING last_heartbeat AT TIME ZONE 'UTC'; END IF; END $m$;
